      state.groups = {};
      for (let i = 0; i < D.groups.length; i++) {
        const g = D.groups[i];
        // The Americans are never quite where the history books put them: each battle shifts them a little.
        const jitterB = g.side === 'A' ? MD.Rng.range(state, 'start-brg', -9, 9) : 0;
        const jitterR = g.side === 'A' ? MD.Rng.range(state, 'start-rng', -25, 25) + (g.id === 'TF17' ? MD.Rng.range(state, 'tf17-gap', -8, 12) : 0) : 0;
        const p = MD.Geo.polar(g.bearing + jitterB, g.range + jitterR);
        state.groups[g.id] = {
          id: g.id,
          side: g.side,
          name: g.name,
          kanji: g.kanji,
          x: p.x,
          y: p.y,
          course: g.course,
          speed: g.speed,
          orderCourse: g.course,
          orderSpeed: g.speed,
          waypoint: null,
          escorts: g.escorts,
          capDrawnUntil: -1,
          capTiredUntil: -1,
          lastAttacked: -999,
          lastAttackFrom: null,
          trail: [{ x: p.x, y: p.y, t: 0 }],
        };
      }
      state.carriers = {};
      state.carrierOrder = [];
      for (let i = 0; i < D.carriers.length; i++) {
        const c = D.carriers[i];
        const types = D.carrierTypes[c.side];
        state.carriers[c.id] = {
          id: c.id,
          side: c.side,
          group: c.group,
          name: c.name,
          kanji: c.kanji,
          islandPort: c.islandPort,
          length: c.length,
          slot: c.slot,
          types: types,
          x: 0,
          y: 0,
          heading: 0,
          detached: false,
          status: 'ok', // ok | damaged | fatal | sunk
          hits: 0,
          torpHits: 0,
          deckOutUntil: -1,
          sinkAt: -1,
          fatalAt: -1,
          hangar: { F: c.F - c.cap, D: c.D, T: c.T },
          arm: { D: 'ship', T: 'ship' },
          cap: { up: c.cap, target: c.cap },
          deck: { state: 'idle', until: 0, pkg: null, strike: null, after: null, task: '' },
          rearm: null,
          recovering: null,
          escortSize: c.escort || D.deck.escortPerCarrier,
          nav: c.nav || D.combat.navJ,
