        c.x = g.x + c.slot.x * Math.cos(a) + c.slot.y * Math.sin(a);
        c.y = g.y - c.slot.x * Math.sin(a) + c.slot.y * Math.cos(a);
        c.heading = g.course;
      }
    },
  };

  MD.Forces = Forces;
})(globalThis.MD = globalThis.MD || {});
